'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const root=process.env.RETOURS_COMPTE_ASSET_DIR||path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
function functions(s){return parse(s).body.filter(n=>n.type==='FunctionDeclaration'&&['ouvrirEcranIdentifiants','rpMessageIdentifiants','afficherMessageIdentifiants','validerIdentifiants','rafraichirEcranCreationApresChangementLangue'].includes(n.id.name)).map(n=>s.slice(n.start,n.end)).join('\n');}
test('compte : 351 bascules, requêtes simulées uniques, verrou et champs conservés, neuf langues et 320/390/1280',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:800}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>r.fulfill({contentType:'text/html',body:read('index.html').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'')}));await page.goto('https://fixture.invalid/index.html');await page.addStyleTag({content:read('style.css')});
 for(const f of ['i18n/i18next.min.js','i18n/resources.js','i18n/connection-resources.js','i18n/i18n-init.js'])await page.addScriptTag({content:read(f)});await page.addScriptTag({content:'let IDENTIFIANTS_EN_COURS=false;let _currentScreenIndex=0;\n'+functions(read('creation.js'))+'\nwindow.lock=()=>IDENTIFIANTS_EN_COURS;window.RP_I18N_ON_LANGUAGE_CHANGE=rafraichirEcranCreationApresChangementLangue;'});
 await page.evaluate(()=>{window.calls=[];window.state={pa:20,arg:300,progression:{stage:2}};window.goTo=n=>{calls.push(['screen',n]);state.screen=n;if(window.mode==='catch')throw Error('fixture');};window.fetch=()=>{throw Error('Réseau réel interdit');};window.snapshot=()=>JSON.stringify({calls,state,lock:lock(),session:JSON.stringify(sessionStorage),storage:Object.fromEntries(Object.entries(localStorage).filter(([k])=>!k.includes('lang'))),email:document.getElementById('auth-email').value,password:document.getElementById('auth-mdp').value,focus:document.activeElement.id,start:document.getElementById('auth-mdp').selectionStart,end:document.getElementById('auth-mdp').selectionEnd,disabled:document.getElementById('auth-valider').disabled});window.setup=mode=>{window.mode=mode;changerLangueRP('fr');ouvrirEcranIdentifiants();calls.length=0;state.screen=0;document.getElementById('auth-email').value=mode==='email'?'invalid':'fixture@example.invalid';document.getElementById('auth-mdp').value=mode==='password'?'court':'mot-de-passe-fictif';document.getElementById('auth-mdp').focus();document.getElementById('auth-mdp').setSelectionRange(2,6);sessionStorage.setItem('fixture','conservé');window.rpAuthAssurerSession=async()=>{calls.push(['session']);if(mode==='pendingSession')return new Promise(r=>window.resolveSession=r);if(mode==='throwsSession')throw Error('fixture');return mode==='noSession'?null:{fixture:true};};window.rpAuthSecuriserCompte=async(...a)=>{calls.push(['secure',...a]);if(mode==='pendingSecure')return new Promise(r=>window.resolveSecure=r);if(mode==='throwsSecure')throw Error('fixture');return mode==='taken'?{ok:false,raison:'email_exists'}:mode==='generic'?{ok:false,raison:'raison libre'}:mode==='null'?null:{ok:true};};if(mode==='unavailable')delete window.rpAuthSecuriserCompte;};});
 const modes=['email','password','unavailable','noSession','taken','generic','null','success','catch','throwsSession','throwsSecure'];
 for(const mode of modes){const before=await page.evaluate(async mode=>{setup(mode);await validerIdentifiants();return {snapshot:snapshot(),calls:calls.map(c=>c[0])};},mode);assert.deepEqual(before.calls,['email','password','unavailable'].includes(mode)?[]:['noSession','throwsSession'].includes(mode)?['session']:['success','catch'].includes(mode)?['session','secure','screen']:['session','secure']);
 for(const lang of langs){const got=await page.evaluate(lang=>{changerLangueRP(lang);const msg=document.getElementById('auth-msg'),btn=document.getElementById('auth-valider');return {same:snapshot(),body:msg.textContent,key:msg.dataset.i18n,expected:msg.dataset.i18n?i18next.t(msg.dataset.i18n):'',dir:msg.dir,button:btn.textContent,expectedButton:i18next.t('auth.submit'),locked:lock(),overflow:document.documentElement.scrollWidth>innerWidth};},lang);assert.equal(got.same,before.snapshot,mode+'/'+lang);assert.equal(got.body,got.expected);assert.equal(got.button,got.expectedButton);assert.equal(got.locked,false);if(got.key)assert.equal(got.dir,lang==='ar'?'rtl':'');assert.equal(got.overflow,false,mode+'/'+lang+'/'+width);}}
 for(const mode of ['pendingSession','pendingSecure']){const before=await page.evaluate(async mode=>{setup(mode);window.pending=validerIdentifiants();await Promise.resolve();await validerIdentifiants();return {snapshot:snapshot(),calls:calls.map(c=>c[0])};},mode);assert.deepEqual(before.calls,mode==='pendingSession'?['session']:['session','secure']);
 for(const lang of langs){const got=await page.evaluate(lang=>{changerLangueRP(lang);const b=document.getElementById('auth-valider');return {same:snapshot(),working:b.textContent,expected:i18next.t('auth.working'),disabled:b.disabled,locked:lock()};},lang);assert.equal(got.same,before.snapshot);assert.equal(got.working,got.expected);assert.equal(got.disabled,true);assert.equal(got.locked,true);}
 await page.evaluate(async mode=>{if(mode==='pendingSession')resolveSession(null);else resolveSecure({ok:false,raison:'fixture'});await pending;},mode);assert.equal(await page.locator('#auth-valider').textContent(),await page.evaluate(()=>i18next.t('auth.submit')));assert.equal(await page.evaluate(()=>lock()),false);}
 // Reopening clears the previous marker; free text is never translated automatically.
 await page.evaluate(()=>ouvrirEcranIdentifiants());for(const lang of langs){await page.evaluate(lang=>changerLangueRP(lang),lang);assert.equal(await page.locator('#auth-msg').textContent(),'');}
 await page.evaluate(()=>afficherMessageIdentifiants('Texte libre <原 & اسم>'));for(const lang of langs){await page.evaluate(lang=>changerLangueRP(lang),lang);assert.equal(await page.locator('#auth-msg').textContent(),'Texte libre <原 & اسم>');assert.equal(await page.locator('#auth-msg').getAttribute('data-i18n'),null);}
 await page.evaluate(async()=>{setup('noSession');await validerIdentifiants();const d=i18next.getResourceBundle('de','translation');delete d.auth.errSession;i18next.removeResourceBundle('de','translation');i18next.addResourceBundle('de','translation',d);changerLangueRP('de');});assert.equal(await page.locator('#auth-msg').textContent(),await page.evaluate(()=>RP_I18N_RESOURCES.fr.translation.auth.errSession));assert.deepEqual(errors,[]);await page.close();}}finally{await browser.close();}
});
